CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated;
GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING (id = auth.uid());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING (id = auth.uid()) WITH CHECK (id = auth.uid());
CREATE FUNCTION public.create_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.profiles(id, display_name) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'display_name', NEW.raw_user_meta_data->>'name', '')); RETURN NEW; END $$;
CREATE TRIGGER tele_create_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_profile();
CREATE TABLE public.user_roles (user_id uuid REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK (role IN ('patient','doctor')), PRIMARY KEY(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role_read ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE TABLE public.doctor_listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES public.profiles(id), name text NOT NULL, specialty text NOT NULL, license text NOT NULL, years integer NOT NULL CHECK(years >= 0), fee integer NOT NULL CHECK(fee > 0), bio text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.doctor_listings TO anon, authenticated;
GRANT ALL ON public.doctor_listings TO service_role;
ALTER TABLE public.doctor_listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY public_doctor_directory ON public.doctor_listings FOR SELECT USING (true);
CREATE TABLE public.bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES public.profiles(id), doctor_id uuid NOT NULL REFERENCES public.doctor_listings(id), patient_name text NOT NULL, starts_at timestamptz NOT NULL, call_type text NOT NULL CHECK(call_type IN ('video','voice')), reason text NOT NULL, status text NOT NULL DEFAULT 'upcoming' CHECK(status IN ('upcoming','cancelled')), payment_status text NOT NULL DEFAULT 'unpaid' CHECK(payment_status IN ('unpaid','paid')), fee integer NOT NULL CHECK(fee > 0), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.bookings TO authenticated;
GRANT ALL ON public.bookings TO service_role;
ALTER TABLE public.bookings ENABLE ROW LEVEL SECURITY;
CREATE POLICY booking_participants_read ON public.bookings FOR SELECT TO authenticated USING (patient_id=auth.uid() OR EXISTS(SELECT 1 FROM public.doctor_listings d WHERE d.id=doctor_id AND d.user_id=auth.uid()));
CREATE UNIQUE INDEX doctor_slot_conflict ON public.bookings(doctor_id, starts_at) WHERE status='upcoming';
CREATE INDEX patient_bookings ON public.bookings(patient_id, starts_at);
CREATE FUNCTION public.register_doctor(p_name text,p_specialty text,p_license text,p_years integer,p_fee integer,p_bio text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; IF length(trim(p_name))<2 OR length(trim(p_license))<3 OR p_specialty NOT IN ('General','Pediatrics','Cardiology','Dermatology','Mental Health','Gynecology') THEN RAISE EXCEPTION 'Check your practice details'; END IF; INSERT INTO public.doctor_listings(user_id,name,specialty,license,years,fee,bio) VALUES(auth.uid(),trim(p_name),p_specialty,trim(p_license),p_years,p_fee,p_bio) ON CONFLICT(user_id) DO UPDATE SET name=excluded.name,specialty=excluded.specialty,license=excluded.license,years=excluded.years,fee=excluded.fee,bio=excluded.bio RETURNING id INTO result; INSERT INTO public.user_roles(user_id,role) VALUES(auth.uid(),'doctor') ON CONFLICT DO NOTHING; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.register_doctor(text,text,text,integer,integer,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.register_doctor(text,text,text,integer,integer,text) TO authenticated;
CREATE FUNCTION public.book_visit(p_doctor uuid,p_starts_at timestamptz,p_type text,p_reason text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; doc public.doctor_listings; pname text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in first'; END IF; SELECT * INTO doc FROM public.doctor_listings WHERE id=p_doctor; IF doc.id IS NULL THEN RAISE EXCEPTION 'Doctor not found'; END IF; IF doc.user_id=auth.uid() THEN RAISE EXCEPTION 'You cannot book yourself'; END IF; IF p_starts_at<=now() THEN RAISE EXCEPTION 'Choose a future appointment'; END IF; IF p_type NOT IN ('video','voice') OR length(trim(p_reason))<3 THEN RAISE EXCEPTION 'Check your appointment details'; END IF; IF extract(minute FROM p_starts_at AT TIME ZONE 'Africa/Nairobi') NOT IN (0,30) OR extract(second FROM p_starts_at) <> 0 THEN RAISE EXCEPTION 'Choose a listed time slot'; END IF; SELECT display_name INTO pname FROM public.profiles WHERE id=auth.uid(); IF length(trim(pname))<2 THEN RAISE EXCEPTION 'Save your name in your profile first'; END IF; INSERT INTO public.bookings(patient_id,doctor_id,patient_name,starts_at,call_type,reason,fee) VALUES(auth.uid(),p_doctor,pname,p_starts_at,p_type,trim(p_reason),doc.fee) RETURNING id INTO result; RETURN result; EXCEPTION WHEN unique_violation THEN RAISE EXCEPTION 'This slot was just booked. Choose another time.'; END $$;
REVOKE ALL ON FUNCTION public.book_visit(uuid,timestamptz,text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.book_visit(uuid,timestamptz,text,text) TO authenticated;
CREATE FUNCTION public.cancel_visit(p_booking uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN UPDATE public.bookings SET status='cancelled' WHERE id=p_booking AND status='upcoming' AND (patient_id=auth.uid() OR EXISTS(SELECT 1 FROM public.doctor_listings d WHERE d.id=doctor_id AND d.user_id=auth.uid())); IF NOT FOUND THEN RAISE EXCEPTION 'Appointment unavailable'; END IF; END $$;
REVOKE ALL ON FUNCTION public.cancel_visit(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.cancel_visit(uuid) TO authenticated;